function __buildGraph(adj) {
  if (!adj.length) return null;
  const nodes = adj.map((_, i) => ({ val: i + 1, neighbors: [] }));
  for (let i = 0; i < adj.length; i += 1) {
    for (const n of adj[i]) nodes[i].neighbors.push(nodes[n - 1]);
  }
  return nodes[0];
}
function __serializeGraph(node) {
  if (!node) return [];
  const visited = new Map();
  const q = [node];
  visited.set(node.val, node);
  while (q.length) {
    const cur = q.shift();
    for (const nb of cur.neighbors) {
      if (!visited.has(nb.val)) {
        visited.set(nb.val, nb);
        q.push(nb);
      }
    }
  }
  return [...visited.keys()]
    .sort((a, b) => a - b)
    .map((k) => visited.get(k).neighbors.map((n) => n.val).sort((a, b) => a - b));
}
function __runCloneGraph(adj) {
  if (!adj.length) return [];
  const cloned = cloneGraph(__buildGraph(adj));
  return __serializeGraph(cloned);
}

