function pacificAtlantic(heights) {
  const rows = heights.length;
  const cols = heights[0].length;
  const pac = new Set();
  const atl = new Set();
  const key = (r, c) => `${r},${c}`;
  const dfs = (r, c, seen, prev) => {
    seen.add(key(r, c));
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    for (const [dr, dc] of dirs) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr < 0 || nc < 0 || nr >= rows || nc >= cols) continue;
      if (heights[nr][nc] < prev) continue;
      if (seen.has(key(nr, nc))) continue;
      dfs(nr, nc, seen, heights[nr][nc]);
    }
  };
  for (let c = 0; c < cols; c += 1) {
    dfs(0, c, pac, heights[0][c]);
    dfs(rows - 1, c, atl, heights[rows - 1][c]);
  }
  for (let r = 0; r < rows; r += 1) {
    dfs(r, 0, pac, heights[r][0]);
    dfs(r, cols - 1, atl, heights[r][cols - 1]);
  }
  const out = [];
  for (const k of pac) {
    if (atl.has(k)) {
      const [r, c] = k.split(",").map(Number);
      out.push([r, c]);
    }
  }
  return out;
}

function canFinish(numCourses, prerequisites) {
  const indeg = Array(numCourses).fill(0);
  const adj = Array.from({ length: numCourses }, () => []);
  for (const [a, b] of prerequisites) {
    adj[b].push(a);
    indeg[a] += 1;
  }
  const q = [];
  for (let i = 0; i < numCourses; i += 1) if (indeg[i] === 0) q.push(i);
  let seen = 0;
  while (q.length) {
    const u = q.shift();
    seen += 1;
    for (const v of adj[u]) {
      indeg[v] -= 1;
      if (indeg[v] === 0) q.push(v);
    }
  }
  return seen === numCourses;
}

function countComponents(n, edges) {
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x) => {
    if (parent[x] !== x) parent[x] = find(parent[x]);
    return parent[x];
  };
  const unite = (a, b) => {
    const pa = find(a);
    const pb = find(b);
    if (pa === pb) return false;
    parent[pa] = pb;
    return true;
  };
  let comps = n;
  for (const [a, b] of edges) if (unite(a, b)) comps -= 1;
  return comps;
}

function validTree(n, edges) {
  if (edges.length !== n - 1) return false;
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x) => {
    if (parent[x] !== x) parent[x] = find(parent[x]);
    return parent[x];
  };
  for (const [a, b] of edges) {
    const pa = find(a);
    const pb = find(b);
    if (pa === pb) return false;
    parent[pa] = pb;
  }
  return true;
}

function alienOrder(words) {
  const adj = new Map();
  const indeg = new Map();
  for (const w of words) {
    for (const c of w) if (!indeg.has(c)) indeg.set(c, 0);
  }
  for (let i = 0; i < words.length - 1; i += 1) {
    const w1 = words[i];
    const w2 = words[i + 1];
    if (w1.length > w2.length && w1.startsWith(w2)) return "";
    let j = 0;
    while (j < w1.length && j < w2.length && w1[j] === w2[j]) j += 1;
    if (j < w1.length && j < w2.length) {
      const a = w1[j];
      const b = w2[j];
      if (!adj.has(a)) adj.set(a, new Set());
      if (!adj.get(a).has(b)) {
        adj.get(a).add(b);
        indeg.set(b, indeg.get(b) + 1);
      }
    }
  }
  const q = [];
  for (const [c, d] of indeg) if (d === 0) q.push(c);
  const out = [];
  while (q.length) {
    const c = q.shift();
    out.push(c);
    for (const nb of adj.get(c) ?? []) {
      indeg.set(nb, indeg.get(nb) - 1);
      if (indeg.get(nb) === 0) q.push(nb);
    }
  }
  return out.length === indeg.size ? out.join("") : "";
}
